204	    /**
205	     * Known E.164 country codes whose national-number length is fixed, used to split the stored
206	     * telephone into its country code and national digits for display: Australia ({@code '61'}) and
207	     * the North American Numbering Plan ({@code '1'}). A number whose country code is not listed is
208	     * split by taking its leading digit as the (minimal) country code.
209	     */
210	    private static final Map<String, Integer> COUNTRY_NATIONAL_LENGTH = Map.of("61", 9, "1", 10);
211	
212	    /**
213	     * The stored E.164 {@link #getTelephone() telephone} formatted for humans: the country code, a
214	     * single space, then the national digits grouped in threes from the left (e.g. the stored
215	     * {@code '+61412345678'} becomes {@code '+61 412 345 678'}). The raw telephone itself stays in
216	     * E.164 form. Returns the stored value unchanged when it is absent or not a {@code '+'}-prefixed
217	     * digit string.
218	     *
219	     * @return the human-readable telephone, or the stored value when it cannot be formatted
220	     */
221	    public String getTelephoneDisplay() {
222	        if (this.telephone == null || !this.telephone.matches("\\+[0-9]+")) {
223	            return this.telephone;
224	        }
225	        String digits = this.telephone.substring(1);
226	        String countryCode = extractCountryCode(digits);
227	        String national = digits.substring(countryCode.length());
228	        StringBuilder display = new StringBuilder("+").append(countryCode);
229	        for (int i = 0; i < national.length(); i += 3) {
230	            display.append(' ').append(national, i, Math.min(i + 3, national.length()));
231	        }
232	        return display.toString();
233	    }
234	
235	    /**
236	     * Splits the country code off an E.164 digit string (country code followed by national digits,
237	     * without the leading {@code '+'}). A country code listed in {@link #COUNTRY_NATIONAL_LENGTH}
238	     * whose required national-number length matches the remaining digits is preferred; failing that,
239	     * the leading digit is used as the country code.
240	     *
241	     * @param digits the E.164 digits without the leading {@code '+'}
242	     * @return the country-code portion of {@code digits}
243	     */
244	    private static String extractCountryCode(String digits) {
245	        for (Map.Entry<String, Integer> entry : COUNTRY_NATIONAL_LENGTH.entrySet()) {
246	            String code = entry.getKey();
247	            if (digits.startsWith(code) && digits.length() - code.length() == entry.getValue()) {
248	                return code;
249	            }
250	        }
251	        return digits.substring(0, 1);
252	    }
