313	     * (e.g. {@code 'NSW-1A2B3C4D-M26'}). Derived from the owner's own customer code and registration
314	     * date; {@code null} when either is absent.
315	     *
316	     * @return the membership number, or {@code null} when it cannot be derived
317	     */
318	    public String getMembershipNumber() {
319	        if (this.customerCode == null || this.registrationDate == null) {
320	            return null;
321	        }
322	        return String.format("%s-M%02d", this.customerCode, fiscalYearOf(this.registrationDate) % 100);
