325	    /**
326	     * The owner's fiscal year, formatted {@code 'FY<YY>'} where {@code YY} is the last two digits of
327	     * the fiscal year of the {@link #getRegistrationDate() business-day-adjusted registration date}.
328	     * The fiscal year starts on 1 July and is named by the calendar year in which it ends, so a
329	     * registration date on or after 1 July belongs to the following calendar year's fiscal year
330	     * (e.g. {@code 2026-07-01} is {@code 'FY27'}) while an earlier date stays in the current one
331	     * (e.g. {@code 2026-06-15} is {@code 'FY26'}). Returns {@code null} when the registration date is
332	     * absent.
333	     *
334	     * @return the fiscal year, or {@code null} when the registration date is absent
335	     */
336	    public String getFiscalYear() {
337	        if (this.registrationDate == null) {
338	            return null;
339	        }
340	        return String.format("FY%02d", fiscalYearOf(this.registrationDate) % 100);
341	    }
