386	    /**
387	     * The owner's membership points, the score the {@link #getMembershipLevel() membership level} is
388	     * derived from. The score starts at 0 and gains: 2 when an email address is present, 1 when the
389	     * owner has no namesakes ({@code namesakeCount} is 0), 2 for a household of 3 or more members
390	     * ({@code householdSize} is at least 3), and 3 when the owner's tenure spans at least one elapsed
391	     * fiscal year (see {@link #getTenureFiscalYears()}). Because a newly created owner has zero
392	     * tenure, the tenure points are never awarded at create time.
393	     *
394	     * @return the membership points, a non-negative integer
395	     */
396	    public Integer getMembershipPoints() {
397	        int points = 0;
398	        boolean hasEmail = this.email != null && !this.email.isBlank();
399	        if (hasEmail) {
400	            points += 2;
401	        }
402	        boolean hasNoNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
403	        if (hasNoNamesakes) {
404	            points += 1;
405	        }
406	        if (this.householdSize != null && this.householdSize >= 3) {
407	            points += 2;
408	        }
409	        Long tenureFiscalYears = getTenureFiscalYears();
410	        if (tenureFiscalYears != null && tenureFiscalYears >= 1) {
411	            points += 3;
412	        }
413	        return points;
414	    }
415	
416	    /**
417	     * The owner's numeric membership level, mapped from the {@link #getMembershipPoints() membership
418	     * points}: level 1 for 0-1 points, level 2 for 2-3 points, level 3 for 4-5 points, and level 4
419	     * for 6 or more points.
420	     *
421	     * @return the membership level, an integer from 1 to 4
422	     */
423	    public Integer getMembershipLevel() {
424	        int points = getMembershipPoints();
425	        if (points <= 1) {
426	            return 1;
427	        }
428	        if (points <= 3) {
429	            return 2;
430	        }
431	        if (points <= 5) {
432	            return 3;
433	        }
434	        return 4;
435	    }
