437	    /**
438	     * The owner's tenure in elapsed fiscal years, the number of fiscal-year boundaries crossed from
439	     * the {@link #getFiscalYear() fiscal year} of the {@link #getRegistrationDate() registration date}
440	     * to the fiscal year of the server's current date (the fiscal year starts on 1 July). An owner
441	     * registered in the current fiscal year has a tenure of 0; one elapsed fiscal year or more is what
442	     * awards the tenure membership points. Returns {@code null} when no registration date has been set
443	     * yet.
444	     *
445	     * @return the tenure in elapsed fiscal years, or {@code null} when the registration date is absent
446	     */
447	    public Long getTenureFiscalYears() {
448	        if (this.registrationDate == null) {
449	            return null;
450	        }
451	        return (long) (fiscalYearOf(LocalDate.now()) - fiscalYearOf(this.registrationDate));
452	    }
